-- Run as the migration owner, never with a browser client.
create extension if not exists pgcrypto;
create table public.profiles (id uuid primary key references auth.users on delete cascade, display_name text not null default '', timezone text not null default 'Europe/Moscow', age_range text not null default '', role text not null default 'user' check(role in ('user','admin')), created_at timestamptz not null default now());
create function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from profiles where id=auth.uid() and role='admin') $$;
create function public.protect_role() returns trigger language plpgsql set search_path=public as $$ begin if current_user in ('authenticated','anon') and (new.role is distinct from old.role or new.id is distinct from old.id) then raise exception 'role immutable'; end if; return new; end $$;
create trigger protect_profile_role before update on profiles for each row execute function protect_role();
create function public.create_profile() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into profiles(id) values(new.id); return new; end $$;
create trigger new_user after insert on auth.users for each row execute function public.create_profile();
create table public.user_preferences(user_id uuid primary key references profiles on delete cascade, nutrition_track text not null check(nutrition_track in ('healthy','vegetarian','raw')), goals jsonb not null default '[]', time_budget_minutes integer not null check(time_budget_minutes in (5,10,15,20,30,45)), activity_level text not null check(activity_level in ('beginner','intermediate')), equipment jsonb not null default '[]', excluded_exercises jsonb not null default '[]', food_allergies jsonb not null default '[]', limitations text not null default '', cold_opt_in boolean not null default false, cold_safety_ack boolean not null default false, safety_ack boolean not null default false check(safety_ack), updated_at timestamptz not null default now(), check(not cold_opt_in or cold_safety_ack));
create table public.notification_preferences(user_id uuid primary key references profiles on delete cascade, reminders_enabled boolean not null default false, preferred_local_time text not null default '19:00' check(preferred_local_time ~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'));
create table public.program_templates(id uuid primary key default gen_random_uuid(),slug text unique not null,title text not null,category text not null,difficulty text not null,duration_days integer not null default 30 check(duration_days=30),published boolean not null default true,created_at timestamptz not null default now());
create table public.program_template_tasks(id uuid primary key default gen_random_uuid(),program_template_id uuid not null references program_templates on delete cascade,day_number integer not null check(day_number between 1 and 30),task_type text not null,payload jsonb not null,estimated_minutes integer not null check(estimated_minutes>=0),sort_order integer not null,unique(program_template_id,day_number,sort_order));
create table public.recipes(id uuid primary key default gen_random_uuid(),slug text unique not null,title text not null,description text not null default '',track_tags jsonb not null,allergens jsonb not null default '[]',ingredients jsonb not null,instructions jsonb not null,servings integer not null check(servings>0),prep_minutes integer not null check(prep_minutes>0),nutrition_notes text not null,image_url text,active boolean not null default true);
create table public.exercises(id uuid primary key default gen_random_uuid(),slug text unique not null,title text not null,category text not null,difficulty text not null,description text not null,instructions jsonb not null,common_mistakes text not null,warnings text not null,reps integer not null default 8,seconds integer not null default 30,rest_seconds integer not null default 20,easier text not null,harder text not null,equipment jsonb not null default '["none"]',media_url text,active boolean not null default true);
create table public.routines(id uuid primary key default gen_random_uuid(),slug text unique not null,title text not null,category text not null,difficulty text not null,estimated_minutes integer not null check(estimated_minutes>0),active boolean not null default true);
create table public.routine_exercises(routine_id uuid not null references routines on delete cascade,exercise_id uuid not null references exercises,sort_order integer not null,reps integer,seconds integer not null,rest_seconds integer not null,primary key(routine_id,sort_order));
create table public.user_programs(id uuid primary key default gen_random_uuid(),user_id uuid not null references profiles on delete cascade,template_id uuid not null references program_templates,start_date date not null,status text not null check(status in ('active','completed')),created_at timestamptz not null default now());
create unique index one_active_program on user_programs(user_id) where status='active';
create table public.daily_plans(id uuid primary key default gen_random_uuid(),user_id uuid not null references profiles on delete cascade,local_date date not null,timezone text not null,adaptation_reason text not null,created_at timestamptz not null default now(),unique(user_id,local_date),unique(id,user_id));
create table public.daily_tasks(id uuid primary key default gen_random_uuid(),daily_plan_id uuid not null,user_id uuid not null references profiles on delete cascade,template_task_id uuid references program_template_tasks on delete set null,category text not null check(category in ('nutrition','activity','stretching','recovery')),title text not null,description text not null,estimated_minutes integer not null check(estimated_minutes>=0),reference_type text,reference_id uuid,status text not null default 'pending' check(status in ('pending','completed','skipped')),completed_at timestamptz,sort_order integer not null,foreign key(daily_plan_id,user_id) references daily_plans(id,user_id) on delete cascade,unique(daily_plan_id,sort_order));
create table public.daily_checkins(id uuid primary key default gen_random_uuid(),user_id uuid not null references profiles on delete cascade,local_date date not null,energy integer not null check(energy between 1 and 5),difficulty integer not null check(difficulty between 1 and 5),mood integer check(mood between 1 and 5),pain_flag boolean not null default false,illness_flag boolean not null default false,notes text not null default '',unique(user_id,local_date));
create table public.user_recipe_favorites(user_id uuid not null references profiles on delete cascade,recipe_id uuid not null references recipes on delete cascade,created_at timestamptz not null default now(),primary key(user_id,recipe_id));
create table public.habit_events(id uuid primary key default gen_random_uuid(),user_id uuid not null references profiles on delete cascade,local_date date not null,category text not null,event_type text not null,metadata jsonb not null default '{}',created_at timestamptz not null default now());
create index tasks_owner on daily_tasks(user_id);create index events_owner_date on habit_events(user_id,local_date);create index checkins_owner_date on daily_checkins(user_id,local_date);
-- Private tables: identity is always checked in the DB, including children.
alter table profiles enable row level security;
create policy profile_read on profiles for select to authenticated using(id=auth.uid());
create policy profile_update on profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid());
-- No client insert: only Auth trigger can create a profile with the default role.
do $$ declare t text; begin foreach t in array array['user_preferences','notification_preferences','user_programs','daily_plans','daily_tasks','daily_checkins','user_recipe_favorites','habit_events'] loop execute format('alter table public.%I enable row level security',t); execute format('create policy own_rows on public.%I for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid())',t); end loop; end $$;
do $$ declare t text; begin foreach t in array array['program_templates','program_template_tasks','recipes','exercises','routines','routine_exercises'] loop execute format('alter table public.%I enable row level security',t); execute format('create policy admin_write on public.%I for all to authenticated using(public.is_admin()) with check(public.is_admin())',t); end loop; end $$;
create policy published_templates on program_templates for select to authenticated using(published);
create policy published_tasks on program_template_tasks for select to authenticated using(exists(select 1 from program_templates p where p.id=program_template_id and p.published));
create policy active_recipes on recipes for select to authenticated using(active);
create policy active_exercises on exercises for select to authenticated using(active);
create policy active_routines on routines for select to authenticated using(active);
create policy active_routine_items on routine_exercises for select to authenticated using(exists(select 1 from routines r where r.id=routine_id and r.active));
-- Serialize competing generators per user/date and create tasks in one transaction.
create function public.save_daily_plan(p_date date,p_timezone text,p_reason text,p_tasks jsonb) returns uuid language plpgsql security invoker set search_path=public as $$
declare plan_id uuid; item jsonb; begin
 if auth.uid() is null then raise exception 'unauthorized'; end if;
 if p_date <> (now() at time zone (select timezone from profiles where id=auth.uid()))::date then raise exception 'only current local date can be generated'; end if;
 perform pg_advisory_xact_lock(hashtextextended(auth.uid()::text||p_date::text,0));
 select id into plan_id from daily_plans where user_id=auth.uid() and local_date=p_date;
 if plan_id is not null then return plan_id; end if;
 insert into daily_plans(user_id,local_date,timezone,adaptation_reason) values(auth.uid(),p_date,p_timezone,p_reason) returning id into plan_id;
 for item in select value from jsonb_array_elements(p_tasks) loop
 insert into daily_tasks(daily_plan_id,user_id,template_task_id,category,title,description,estimated_minutes,reference_type,reference_id,sort_order) values(plan_id,auth.uid(),nullif(item->>'template_task_id','')::uuid,item->>'category',item->>'title',item->>'description',(item->>'estimated_minutes')::int,item->>'reference_type',nullif(item->>'reference_id','')::uuid,(item->>'sort_order')::int);
 end loop;return plan_id;end $$;
create function public.complete_onboarding(p_profile jsonb,p_preferences jsonb,p_template uuid,p_date date) returns void language plpgsql security invoker set search_path=public as $$ begin
 if auth.uid() is null then raise exception 'unauthorized'; end if;
 perform pg_advisory_xact_lock(hashtextextended(auth.uid()::text,0));
 update profiles set display_name=p_profile->>'display_name',timezone=p_profile->>'timezone',age_range=p_profile->>'age_range' where id=auth.uid();
 insert into user_preferences(user_id,nutrition_track,goals,time_budget_minutes,activity_level,equipment,excluded_exercises,food_allergies,limitations,cold_opt_in,cold_safety_ack,safety_ack) values(auth.uid(),p_preferences->>'nutrition_track',p_preferences->'goals',(p_preferences->>'time_budget_minutes')::int,p_preferences->>'activity_level',p_preferences->'equipment',p_preferences->'excluded_exercises',p_preferences->'food_allergies',p_preferences->>'limitations',(p_preferences->>'cold_opt_in')::boolean,(p_preferences->>'cold_safety_ack')::boolean,(p_preferences->>'safety_ack')::boolean) on conflict(user_id) do update set nutrition_track=excluded.nutrition_track,goals=excluded.goals,time_budget_minutes=excluded.time_budget_minutes,activity_level=excluded.activity_level,equipment=excluded.equipment,excluded_exercises=excluded.excluded_exercises,food_allergies=excluded.food_allergies,limitations=excluded.limitations,cold_opt_in=excluded.cold_opt_in,cold_safety_ack=excluded.cold_safety_ack,safety_ack=excluded.safety_ack,updated_at=now();
 insert into notification_preferences(user_id,reminders_enabled,preferred_local_time) values(auth.uid(),(p_preferences->>'reminders_enabled')::boolean,p_preferences->>'preferred_local_time') on conflict(user_id) do update set reminders_enabled=excluded.reminders_enabled,preferred_local_time=excluded.preferred_local_time;
 update user_programs set status='completed' where user_id=auth.uid() and status='active';
 insert into user_programs(user_id,template_id,start_date,status) values(auth.uid(),p_template,p_date,'active'); end $$;
create function public.start_program(p_template uuid,p_date date) returns void language plpgsql security invoker set search_path=public as $$ begin
 if auth.uid() is null then raise exception 'unauthorized'; end if;
 perform pg_advisory_xact_lock(hashtextextended(auth.uid()::text,0));
 if not exists(select 1 from program_templates where id=p_template and published) then raise exception 'template unavailable'; end if;
 update user_programs set status='completed' where user_id=auth.uid() and status='active';insert into user_programs(user_id,template_id,start_date,status) values(auth.uid(),p_template,p_date,'active');end $$;
create function public.delete_my_data() returns void language plpgsql security invoker set search_path=public as $$ begin
 delete from habit_events where user_id=auth.uid();delete from daily_checkins where user_id=auth.uid();delete from daily_plans where user_id=auth.uid();delete from user_programs where user_id=auth.uid();delete from user_recipe_favorites where user_id=auth.uid();delete from notification_preferences where user_id=auth.uid();delete from user_preferences where user_id=auth.uid();update profiles set display_name='',age_range='' where id=auth.uid();end $$;
revoke all on function public.save_daily_plan(date,text,text,jsonb),public.complete_onboarding(jsonb,jsonb,uuid,date),public.start_program(uuid,date),public.delete_my_data() from public,anon;
grant execute on function public.save_daily_plan(date,text,text,jsonb),public.complete_onboarding(jsonb,jsonb,uuid,date),public.start_program(uuid,date),public.delete_my_data() to authenticated;
-- Optional images only. No user health data belongs in this public bucket.
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('catalog-images','catalog-images',true,2097152,array['image/png','image/jpeg','image/webp']) on conflict do nothing;
create policy catalog_image_read on storage.objects for select using(bucket_id='catalog-images');
create policy catalog_image_admin on storage.objects for all to authenticated using(bucket_id='catalog-images' and public.is_admin()) with check(bucket_id='catalog-images' and public.is_admin());
